function firstSentences(text, count) {
  const sentences = text.match(/[^.]+\./g) || [text];
  return sentences.slice(0, count).join(" ").trim();
}

function localAnswer(scored) {
  if (!scored || scored.length === 0) {
    return "No live model connection right now, so here's what retrieval alone can surface — try one of the suggested questions, or reach out directly below.";
  }
  const top = scored[0];
  const lead = `${firstSentences(top.text, 2)} [${top.id}]`;
  if (scored.length > 1) {
    const second = scored[1];
    const support = `${firstSentences(second.text, 1)} [${second.id}]`;
    return `${lead} ${support}`;
  }
  return lead;
}

function TypedLines({ lines, onDone }) {
  const [rendered, setRendered] = useState([]);
  const idxRef = useRef(0);
  const charRef = useRef(0);

  useEffect(() => {
    let cancelled = false;
    let current = [];
    setRendered([]);

    function step() {
      if (cancelled) return;
      const li = idxRef.current;
      if (li >= lines.length) {
        onDone && onDone();
        return;
      }
      const line = lines[li];
      const ci = charRef.current;
      if (ci <= line.text.length) {
        const partial = line.text.slice(0, ci);
        const next = [...current];
        next[li] = { ...line, text: partial };
        current = next;
        setRendered(next);
        charRef.current += 1;
        setTimeout(step, line.speed || 14);
      } else {
        idxRef.current += 1;
        charRef.current = 0;
        setTimeout(step, line.pause || 220);
      }
    }
    const t = setTimeout(step, 300);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [lines]);

  return (
    <>
      {rendered.map((l, i) => (
        <div
          key={i}
          style={{
            color: l.color || TOKENS.text,
            fontFamily: "'IBM Plex Mono', monospace",
            fontSize: "13.5px",
            lineHeight: 1.7,
            whiteSpace: "pre-wrap",
          }}
        >
          {l.prompt && <span style={{ color: TOKENS.teal }}>{l.prompt} </span>}
          {l.text}
        </div>
      ))}
    </>
  );
}

function ScoreBar({ value }) {
  return (
    <div
      style={{
        width: 60,
        height: 4,
        background: "rgba(79,195,183,0.15)",
        borderRadius: 2,
        overflow: "hidden",
        flexShrink: 0,
      }}
    >
      <div
        style={{
          width: `${Math.round(value * 100)}%`,
          height: "100%",
          background: TOKENS.teal,
          borderRadius: 2,
        }}
      />
    </div>
  );
}

function renderAnswer(text) {
  const parts = text.split(/(\[DOC-\d\])/g);
  return parts.map((p, i) => {
    const m = p.match(/^\[DOC-(\d)\]$/);
    if (m) {
      return (
        <span
          key={i}
          style={{
            color: TOKENS.teal,
            border: `1px solid ${TOKENS.tealDim}`,
            borderRadius: 4,
            padding: "0 5px",
            fontSize: "11.5px",
            fontFamily: "'IBM Plex Mono', monospace",
            marginLeft: 2,
            whiteSpace: "nowrap",
          }}
        >
          {p}
        </span>
      );
    }
    return <span key={i}>{p}</span>;
  });
}


